import {randomUUID} from 'node:crypto';
import {crmPermissions} from './crm-work-access.mjs';
import {requireLiveSession} from './transaction-permissions.mjs';
const types=new Set(['text','textarea','number','currency','date','time','checkbox','select','multiselect','email','phone','url']);
const text=(v,max)=>{if(typeof v!=='string'||!v.trim()||v.length>max||/[\u0000-\u001f\u007f]/.test(v))throw Error('invalid_input');return v.trim()};
const id=v=>text(v,100);
const safeCard=c=>({id:c.id,board_id:c.board_id,column_id:c.column_id,position:c.position,assigned_user_id:c.assigned_user_id,version:c.version,archived_at:c.archived_at});
const version=v=>{if(!Number.isSafeInteger(v)||v<1)throw Error('invalid_input');return v};
async function permission(db,user,operation){if(!user?.id)throw Error('forbidden');const s=await db.query('SELECT scope FROM crm_work_user_visibility WHERE user_id=$1',[user.id]);const a=crmPermissions(user,s.rows[0]?.scope||'inherit');if(!a||(operation&&!a[operation]))throw Error('forbidden');return a}
const tx=async(db,user,operation,fn)=>{const c=await db.connect();try{await c.query('BEGIN');await c.query('SELECT pg_advisory_xact_lock($1)',[68499002]);if(!user?.id)throw Error('forbidden');const row=(await c.query('SELECT id,role,active FROM users WHERE id=$1 FOR SHARE',[user.id])).rows[0];if(!row?.active)throw Error('forbidden');await requireLiveSession(c,user.id);const p=(await c.query('SELECT permission FROM staff_permissions WHERE user_id=$1 UNION SELECT unnest(r.permissions) AS permission FROM access_roles r JOIN access_role_assignments a ON a.role_id=r.id WHERE a.user_id=$1',[user.id])).rows.map(x=>x.permission);const access=await permission(c,{id:row.id,role:row.role,permissions:p},operation);const result=await fn(c,access);await c.query('COMMIT');return result}catch(e){await c.query('ROLLBACK').catch(()=>{});throw e}finally{c.release()}};
export async function listBoards(db,user,archived=false){if(typeof archived!=='boolean')throw Error('invalid_input');return tx(db,user,null,async(c,a)=>{if(archived&&!a.manage)throw Error('forbidden');return (await c.query('SELECT * FROM crm_work_boards WHERE (archived_at IS NOT NULL)=$1 ORDER BY position,id LIMIT 200',[archived])).rows})}
export async function saveBoard(db,user,input){
 await permission(db,user,'manage');const name=text(input?.name,120);
 return tx(db,user,'manage',async c=>{let r;if(!input.id)r=await c.query('INSERT INTO crm_work_boards(id,name,created_by,position) VALUES($1,$2,$3,(SELECT coalesce(max(position)+1,0) FROM crm_work_boards)) RETURNING *',[randomUUID(),name,user.id]);else r=await c.query('UPDATE crm_work_boards SET name=$1,version=version+1,updated_at=now() WHERE id=$2 AND version=$3 AND archived_at IS NULL RETURNING *',[name,id(input.id),version(input.version)]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action) VALUES($1,$2,$3)',[r.rows[0].id,user.id,input.id?'board_updated':'board_created']);return r.rows[0]});
}
export async function setupFirstBoard(db,user,input){
 const name=text(input?.name,120),columns=input?.columns;
 if(!Array.isArray(columns)||columns.length<1||columns.length>8)throw Error('invalid_input');
 const checked=columns.map(x=>{const name=text(x?.name,120),color=x?.color;if(typeof color!=='string'||!/^[a-z]{1,24}$/.test(color))throw Error('invalid_input');return {name,color}});
 return tx(db,user,'manage',async c=>{
  if((await c.query('SELECT 1 FROM crm_work_boards LIMIT 1')).rowCount)throw Error('version_conflict');
  const board=(await c.query('INSERT INTO crm_work_boards(id,name,created_by,position) VALUES($1,$2,$3,0) RETURNING *',[randomUUID(),name,user.id])).rows[0];
  await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action) VALUES($1,$2,$3)',[board.id,user.id,'board_created']);
  for(let i=0;i<checked.length;i++){const column=checked[i];const columnId=randomUUID();await c.query('INSERT INTO crm_work_columns(id,board_id,name,color,position) VALUES($1,$2,$3,$4,$5)',[columnId,board.id,column.name,column.color,i]);await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board.id,user.id,'column_created',JSON.stringify({column_id:columnId})])}
  return board;
 });
}
export async function archiveBoard(db,user,input){if(typeof input?.archived!=='boolean')throw Error('invalid_input');return tx(db,user,'manage',async c=>{const r=await c.query('UPDATE crm_work_boards SET archived_at=CASE WHEN $1 THEN now() ELSE NULL END,version=version+1,updated_at=now() WHERE id=$2 AND version=$3 AND (archived_at IS NOT NULL)<>$1 RETURNING id,name,archived_at,version',[input.archived,id(input.id),version(input.version)]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action) VALUES($1,$2,$3)',[r.rows[0].id,user.id,input.archived?'board_archived':'board_restored']);return r.rows[0]})}
export async function listColumns(db,user,board,archived=false){if(typeof archived!=='boolean')throw Error('invalid_input');return tx(db,user,null,async(c,a)=>{if(archived&&!a.manage)throw Error('forbidden');return (await c.query('SELECT * FROM crm_work_columns WHERE board_id=$1 AND (archived_at IS NOT NULL)=$3 AND EXISTS(SELECT 1 FROM crm_work_boards b WHERE b.id=board_id AND (b.archived_at IS NULL OR $2::boolean)) ORDER BY position,id LIMIT 200',[id(board),a.manage,archived])).rows})}
export async function saveColumn(db,user,input){await permission(db,user,'manage');const board=id(input.boardId),name=text(input.name,120),color=input.color??'slate';if(typeof color!=='string'||!/^[a-z]{1,24}$/.test(color))throw Error('invalid_input');return tx(db,user,'manage',async c=>{let b=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(!b.rowCount)throw Error('not_found');let r;if(!input.id)r=await c.query('INSERT INTO crm_work_columns(id,board_id,name,color,position) VALUES($1,$2,$3,$4,(SELECT coalesce(max(position)+1,0) FROM crm_work_columns WHERE board_id=$2)) RETURNING *',[randomUUID(),board,name,color]);else r=await c.query('UPDATE crm_work_columns SET name=$1,color=$2,version=version+1 WHERE id=$3 AND board_id=$4 AND version=$5 AND archived_at IS NULL RETURNING *',[name,color,id(input.id),board,version(input.version)]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,input.id?'column_updated':'column_created',JSON.stringify({column_id:r.rows[0].id})]);return r.rows[0]})}
export async function duplicateColumn(db,user,input){
 const board=id(input?.boardId),column=id(input?.id),v=version(input?.version),name=text(input?.name,120);
 return tx(db,user,'manage',async c=>{
  if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board])).rowCount)throw Error('not_found');
  const source=await c.query('SELECT color FROM crm_work_columns WHERE id=$1 AND board_id=$2 AND version=$3 AND archived_at IS NULL',[column,board,v]);if(!source.rowCount)throw Error('version_conflict');
  if((await c.query('SELECT count(*)::int AS n FROM crm_work_columns WHERE board_id=$1',[board])).rows[0].n>=200)throw Error('limit_exceeded');
  const r=await c.query('INSERT INTO crm_work_columns(id,board_id,name,color,position) VALUES($1,$2,$3,$4,(SELECT coalesce(max(position)+1,0) FROM crm_work_columns WHERE board_id=$2)) RETURNING *',[randomUUID(),board,name,source.rows[0].color]);
  await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,'column_duplicated',JSON.stringify({source_column_id:column,column_id:r.rows[0].id})]);return r.rows[0];
 });
}
export async function archiveColumn(db,user,input){if(typeof input?.archived!=='boolean')throw Error('invalid_input');const board=id(input.boardId),column=id(input.id);return tx(db,user,'manage',async c=>{const b=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(!b.rowCount)throw Error('not_found');if(input.archived&&(await c.query('SELECT 1 FROM crm_work_cards WHERE board_id=$1 AND column_id=$2 LIMIT 1',[board,column])).rowCount)throw Error('column_not_empty');const r=await c.query('UPDATE crm_work_columns SET archived_at=CASE WHEN $1 THEN now() ELSE NULL END,archived_by=CASE WHEN $1 THEN $2 ELSE NULL END,version=version+1 WHERE id=$3 AND board_id=$4 AND version=$5 AND (archived_at IS NOT NULL)<>$1 RETURNING *',[input.archived,user.id,column,board,version(input.version)]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,input.archived?'column_archived':'column_restored',JSON.stringify({column_id:column})]);return r.rows[0]})}
export async function setColumnAutomation(db,user,input){
 const board=id(input?.boardId),column=id(input?.id),v=version(input?.version),days=input?.archiveAfterDays;
 if(days!==null&&(!Number.isSafeInteger(days)||days<1||days>3650))throw Error('invalid_input');
 return tx(db,user,'manage',async(c,a)=>{
  if(!a.admin)throw Error('forbidden');
  if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board])).rowCount)throw Error('not_found');
  const r=await c.query('UPDATE crm_work_columns SET archive_after_days=$1,archive_rule_by=CASE WHEN $1::integer IS NULL THEN NULL ELSE $2 END,version=version+1 WHERE board_id=$3 AND id=$4 AND version=$5 AND archived_at IS NULL RETURNING *',[days,user.id,board,column,v]);
  if(!r.rowCount)throw Error('version_conflict');
  await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,'automation_changed',JSON.stringify({column_id:column,archive_after_days:days})]);return r.rows[0];
 });
}
// Runs only when the CRM module is explicitly enabled. No external calls or deletion.
export async function runColumnAutomation(db){
 if(process.env.PC_LEASE_CRM_WORK_TEST!=='1'&&process.env.PC_LEASE_CRM_WORK_ENABLED!=='1')throw Error('forbidden');
 const c=await db.connect();try{
  await c.query('BEGIN');await c.query('SELECT pg_advisory_xact_lock($1)',[68499002]);
  const due=await c.query(`SELECT card.id,card.board_id,col.archive_rule_by AS actor FROM crm_work_cards card JOIN crm_work_columns col ON col.id=card.column_id AND col.board_id=card.board_id JOIN crm_work_boards b ON b.id=card.board_id JOIN users u ON u.id=col.archive_rule_by WHERE card.archived_at IS NULL AND col.archived_at IS NULL AND b.archived_at IS NULL AND col.archive_after_days IS NOT NULL AND card.column_entered_at<=now()-make_interval(days=>col.archive_after_days) AND u.active AND u.role='admin' ORDER BY card.id LIMIT 100 FOR UPDATE OF card`);
  for(const row of due.rows){await c.query('UPDATE crm_work_cards SET archived_at=now(),archived_by=$1,version=version+1,updated_at=now() WHERE id=$2',[row.actor,row.id]);await c.query('INSERT INTO crm_work_card_events(board_id,card_id,actor_id,action,details) VALUES($1,$2,$3,$4,$5)',[row.board_id,row.id,row.actor,'auto_archived',JSON.stringify({source:'column_rule'})])}
  await c.query('COMMIT');return due.rowCount;
 }catch(e){await c.query('ROLLBACK').catch(()=>{});throw e}finally{c.release()}
}
export async function listFields(db,user,board){return tx(db,user,null,async(c,a)=>(await c.query('SELECT * FROM crm_work_field_definitions WHERE board_id=$1 AND (visible OR $2::boolean) AND EXISTS(SELECT 1 FROM crm_work_boards b WHERE b.id=board_id AND (b.archived_at IS NULL OR $2::boolean)) ORDER BY position,id LIMIT 200',[id(board),a.manage])).rows)}
export async function listPrintTemplates(db,user,boardId){
 const board=id(boardId);return tx(db,user,null,async(c,a)=>{
  const r=await c.query('SELECT t.* FROM crm_work_print_templates t JOIN crm_work_boards b ON b.id=t.board_id WHERE t.board_id=$1 AND b.archived_at IS NULL AND (t.enabled OR $2::boolean) ORDER BY t.name,t.id LIMIT 100',[board,a.manage]);
  if(a.manage)return r.rows;
  const visible=new Set((await c.query('SELECT id FROM crm_work_field_definitions WHERE board_id=$1 AND visible=true',[board])).rows.map(x=>x.id));
  return r.rows.map(t=>({...t,field_ids:t.field_ids.filter(f=>visible.has(f))}));
 });
}
export async function getPrintCard(db,user,boardId,cardId,templateId){
 const board=id(boardId),card=id(cardId),template=id(templateId);
 return tx(db,user,null,async(c,a)=>{
  const result=await c.query(`SELECT c.title,c.description,c.custom_data,t.title AS template_title,t.include_description,t.field_ids,t.orientation,t.footer,t.direction,t.hide_empty,t.show_logo,t.show_company_details,t.company_details,t.show_card_metadata,col.name AS column_name,c.created_at,c.updated_at,COALESCE(NULLIF(trim(concat_ws(' ',u.first_name,u.last_name)),''),u.email) AS assignee_name FROM crm_work_cards c JOIN crm_work_boards b ON b.id=c.board_id JOIN crm_work_columns col ON col.id=c.column_id AND col.board_id=c.board_id LEFT JOIN users u ON u.id=c.assigned_user_id JOIN crm_work_print_templates t ON t.board_id=c.board_id AND t.id=$3 AND t.enabled WHERE c.board_id=$1 AND c.id=$2 AND b.archived_at IS NULL AND b.print_enabled AND ($4::boolean OR c.assigned_user_id=$5)`,[board,card,template,a.all,user.id]);
  if(!result.rowCount)throw Error('not_found');
  const row=result.rows[0],visible=await c.query('SELECT id,internal_name,display_name FROM crm_work_field_definitions WHERE board_id=$1 AND visible=true AND id=ANY($2::text[])',[board,row.field_ids]);
  const byId=new Map(visible.rows.map(f=>[f.id,f]));
  return {title:row.template_title,orientation:row.orientation,footer:row.footer,direction:row.direction,showLogo:row.show_logo,companyDetails:row.show_company_details?row.company_details:null,metadata:row.show_card_metadata?{column:row.column_name,assignee:row.assignee_name,createdAt:row.created_at,updatedAt:row.updated_at}:null,cardTitle:row.title,description:row.include_description?row.description:null,fields:row.field_ids.filter(key=>byId.has(key)).map(key=>{const f=byId.get(key);return {label:f.display_name,value:row.custom_data[f.internal_name]??null}}).filter(f=>!row.hide_empty||(f.value!==null&&f.value!==''&&(!Array.isArray(f.value)||f.value.length>0)))};
 });
}
