 if(!['portrait','landscape'].includes(orientation)||typeof footer!=='string'||footer.length>2000||!['rtl','ltr'].includes(direction)||typeof hideEmpty!=='boolean'||typeof enabled!=='boolean'||typeof isDefault!=='boolean'||(isDefault&&!enabled)||[showLogo,showCompanyDetails,showCardMetadata].some(v=>typeof v!=='boolean')||typeof companyDetails!=='string'||companyDetails.length>2000)throw Error('invalid_input');
