 if(!Array.isArray(options)||options.length>100||options.some(o=>typeof o!=='string'||!o.trim()||o.length>100)||new Set(options).size!==options.length)throw Error('invalid_input');
 if(!['select','multiselect'].includes(input.fieldType)&&options.length)throw Error('invalid_input');
