function validateValue(f,v){
 if(v===null||v===undefined||v===''||(Array.isArray(v)&&!v.length)){if(f.required)throw Error('invalid_input');return null}
 const config=f.config&&typeof f.config==='object'?f.config:{};
 if(['number','currency'].includes(f.field_type)){if(typeof v!=='number'||!Number.isFinite(v)||(config.min!=null&&v<config.min)||(config.max!=null&&v>config.max))throw Error('invalid_input');return v}
 if(f.field_type==='checkbox'){if(typeof v!=='boolean')throw Error('invalid_input');return v}
 if(f.field_type==='multiselect'){if(!Array.isArray(v)||v.length>100||new Set(v).size!==v.length||v.some(x=>typeof x!=='string'||!f.options.includes(x)))throw Error('invalid_input');return v}
 if(typeof v!=='string'||v.length>4000||(config.max_length!=null&&v.length>config.max_length))throw Error('invalid_input');
 if(f.field_type==='select'&&!f.options.includes(v))throw Error('invalid_input');
 if(f.field_type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))throw Error('invalid_input');
 if(f.field_type==='url'){try{if(!['http:','https:'].includes(new URL(v).protocol))throw Error()}catch{throw Error('invalid_input')}}
 if(f.field_type==='date'){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('invalid_input');const date=new Date(v+'T00:00:00Z');if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==v)throw Error('invalid_input')}
 if(f.field_type==='time'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))throw Error('invalid_input');return v
}
export async function listCards(db,user,{boardId,archived=false,search='',offset=0,assignee='',recentDays=0}){
 if(typeof search!=='string'||search.length>200||!Number.isInteger(offset)||offset<0||offset>100000||typeof archived!=='boolean'||typeof assignee!=='string'||assignee.length>100||![0,7,30].includes(recentDays))throw Error('invalid_input');
 return tx(db,user,null,async(c,a)=>{const source=`SELECT c.id,c.board_id,c.column_id,c.position,c.title,c.description,filtered.data AS custom_data,CASE WHEN $7::boolean THEN c.organization_id ELSE NULL END AS organization_id,CASE WHEN $8::boolean THEN c.request_id ELSE NULL END AS request_id,c.assigned_user_id,c.version,c.created_at,c.updated_at,c.archived_at FROM crm_work_cards c CROSS JOIN LATERAL (SELECT CASE WHEN $6::boolean THEN c.custom_data ELSE c.custom_data - ARRAY(SELECT f.internal_name FROM crm_work_field_definitions f WHERE f.board_id=c.board_id AND f.visible=false) END AS data) filtered WHERE c.board_id=$1 AND EXISTS(SELECT 1 FROM crm_work_boards b WHERE b.id=c.board_id AND (b.archived_at IS NULL OR $6::boolean)) AND (c.archived_at IS ${archived?'NOT ':''}NULL) AND ($5::integer>=0) AND ($2::boolean OR c.assigned_user_id=$3) AND ($9='' OR c.assigned_user_id=$9) AND ($10::integer=0 OR c.created_at>=now()-make_interval(days=>$10::integer)) AND ($4='' OR position(lower($4) in lower(c.title || ' ' || c.description || ' ' || filtered.data::text))>0 OR (regexp_replace($4,'[0-9()+ .-]','','g')='' AND regexp_replace($4,'[^0-9]','','g')<>'' AND position(regexp_replace($4,'[^0-9]','','g') in regexp_replace(c.title || ' ' || c.description || ' ' || filtered.data::text,'[^0-9]','','g'))>0))`;const params=[id(boardId),a.all,a.userId,search.trim(),offset,a.manage,a.admin,a.orders,assignee,recentDays];const result=await c.query(source+' ORDER BY c.column_id,c.position,c.id LIMIT 101 OFFSET $5',params);const countResult=await c.query('SELECT column_id,count(*)::int AS count FROM ('+source+') AS matched GROUP BY column_id',params);
 return {cards:result.rows.slice(0,100),hasMore:result.rows.length>100,columnCounts:Object.fromEntries(countResult.rows.map(row=>[row.column_id,row.count]))}});
}
export async function saveCard(db,user,input){const a=await permission(db,user,'edit');const board=id(input.boardId),column=id(input.columnId),title=text(input.title,200);if(typeof input.description!=='string'||input.description.length>10000||!input.customData||typeof input.customData!=='object'||Array.isArray(input.customData))throw Error('invalid_input');return tx(db,user,'edit',async(c,a)=>{const b=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(!b.rowCount)throw Error('not_found');const col=await c.query('SELECT id FROM crm_work_columns WHERE board_id=$1 AND id=$2 AND archived_at IS NULL FOR UPDATE',[board,column]);if(!col.rowCount)throw Error('not_found');if(input.organizationId!==undefined&&!a.admin)throw Error('forbidden');if(input.requestId!==undefined&&!a.orders)throw Error('forbidden');const org=input.organizationId==null||input.organizationId===''?null:id(input.organizationId),request=input.requestId==null||input.requestId===''?null:id(input.requestId);const fields=(await c.query('SELECT * FROM crm_work_field_definitions WHERE board_id=$1',[board])).rows;let previous={},previousCard=null;if(input.id){const old=await c.query('SELECT title,description,assigned_user_id,organization_id,request_id,custom_data FROM crm_work_cards WHERE id=$1 AND board_id=$2 AND archived_at IS NULL AND ($3::boolean OR assigned_user_id=$4) FOR UPDATE',[id(input.id),board,a.all,user.id]);if(!old.rowCount)throw Error('version_conflict');previousCard=old.rows[0];previous=previousCard.custom_data}const keys=new Set(fields.map(x=>x.internal_name));if(Object.keys(input.customData).some(k=>!keys.has(k)))throw Error('invalid_input');if(a.all&&input.assignedUserId){const target=await c.query("SELECT 1 FROM users u WHERE u.id=$1 AND u.active=true AND (u.role='admin' OR EXISTS(SELECT 1 FROM staff_permissions p WHERE p.user_id=u.id AND p.permission='crm_boards_view') OR EXISTS(SELECT 1 FROM access_role_assignments ar JOIN access_roles r ON r.id=ar.role_id WHERE ar.user_id=u.id AND 'crm_boards_view'=ANY(r.permissions)))",[id(input.assignedUserId)]);if(!target.rowCount)throw Error('invalid_input')}const values={};for(const f of fields){const incoming=input.customData[f.internal_name];if((f.read_only||!f.visible)&&!a.manage){if(incoming!==undefined&&JSON.stringify(incoming)!==JSON.stringify(previous[f.internal_name]))throw Error('forbidden');const retained=previous[f.internal_name]??(!input.id?f.default_value:null);const v=validateValue(f,retained);if(v!==null)values[f.internal_name]=v;continue}const effective=incoming===undefined?(input.id?previous[f.internal_name]:f.default_value):incoming;const v=validateValue(f,effective);if(v!==null)values[f.internal_name]=v}let r;if(!input.id){const assignee=a.all&&input.assignedUserId?id(input.assignedUserId):user.id;r=await c.query(`INSERT INTO crm_work_cards(id,board_id,column_id,position,title,description,custom_data,assigned_user_id,created_by,organization_id,request_id) VALUES($1,$2,$3,(SELECT coalesce(max(position)+1,0) FROM crm_work_cards WHERE board_id=$2 AND column_id=$3),$4,$5,$6,$7,$8,$9,$10) RETURNING *`,[randomUUID(),board,column,title,input.description,JSON.stringify(values),assignee,user.id,org,request])}else{r=await c.query(`UPDATE crm_work_cards SET title=$1,description=$2,custom_data=$3,assigned_user_id=CASE WHEN $8::boolean AND $10::text IS NOT NULL THEN $10 ELSE assigned_user_id END,organization_id=CASE WHEN $11::boolean THEN $12 ELSE organization_id END,request_id=CASE WHEN $13::boolean THEN $14 ELSE request_id END,version=version+1,updated_at=now() WHERE id=$5 AND board_id=$6 AND column_id=$4 AND version=$7 AND archived_at IS NULL AND ($8::boolean OR assigned_user_id=$9) RETURNING *`,[title,input.description,JSON.stringify(values),column,id(input.id),board,version(input.version),a.all,user.id,a.all&&input.assignedUserId?id(input.assignedUserId):null,input.organizationId!==undefined,org,input.requestId!==undefined,request]);if(!r.rowCount)throw Error('version_conflict')}const changed=[];if(previousCard){if(previousCard.title!==title)changed.push('title');if(previousCard.description!==input.description)changed.push('description');if(previousCard.assigned_user_id!==r.rows[0].assigned_user_id)changed.push('assignee');if(previousCard.organization_id!==r.rows[0].organization_id)changed.push('organization');if(previousCard.request_id!==r.rows[0].request_id)changed.push('request');for(const f of fields)if(JSON.stringify(previous[f.internal_name]??null)!==JSON.stringify(values[f.internal_name]??null))changed.push('field:'+f.internal_name)}await c.query('INSERT INTO crm_work_card_events(board_id,card_id,actor_id,action,details) VALUES($1,$2,$3,$4,$5)',[board,r.rows[0].id,user.id,input.id?'updated':'created',JSON.stringify({changed})]);return safeCard(r.rows[0])})}
export async function archiveCard(db,user,input){if(typeof input?.archived!=='boolean')throw Error('invalid_input');const a=await permission(db,user,'archive');return tx(db,user,'archive',async(c,a)=>{const b=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[id(input.boardId)]);if(!b.rowCount)throw Error('not_found');const r=await c.query(`UPDATE crm_work_cards SET archived_at=CASE WHEN $1 THEN now() ELSE NULL END,archived_by=CASE WHEN $1 THEN $2 ELSE NULL END,version=version+1,updated_at=now() WHERE id=$3 AND board_id=$4 AND version=$5 AND (archived_at IS NOT NULL)<>$1 AND ($6::boolean OR assigned_user_id=$2) RETURNING *`,[!!input.archived,user.id,id(input.id),id(input.boardId),version(input.version),a.all]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_card_events(board_id,card_id,actor_id,action) VALUES($1,$2,$3,$4)',[r.rows[0].board_id,r.rows[0].id,user.id,input.archived?'archived':'restored']);return safeCard(r.rows[0])})}
// Permanent deletion is restricted to administrators and requires an archived item.
// The immutable event log contains identifiers/actions, never copied card values.
export async function permanentlyDeleteCard(db,user,input){
 if(input?.confirmation!=='DELETE')throw Error('invalid_input');const board=id(input.boardId),card=id(input.id),v=version(input.version);
 return tx(db,user,null,async(c,a)=>{if(!a.admin)throw Error('forbidden');if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board])).rowCount)throw Error('not_found');const r=await c.query('DELETE FROM crm_work_cards WHERE board_id=$1 AND id=$2 AND version=$3 AND archived_at IS NOT NULL RETURNING id',[board,card,v]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,'card_permanently_deleted',JSON.stringify({card_id:card})]);return {ok:true}});
}
export async function permanentlyDeleteColumn(db,user,input){
 if(input?.confirmation!=='DELETE')throw Error('invalid_input');const board=id(input.boardId),column=id(input.id),v=version(input.version);
 return tx(db,user,null,async(c,a)=>{if(!a.admin)throw Error('forbidden');if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board])).rowCount)throw Error('not_found');if((await c.query('SELECT 1 FROM crm_work_cards WHERE board_id=$1 AND column_id=$2 LIMIT 1',[board,column])).rowCount)throw Error('column_not_empty');const r=await c.query('DELETE FROM crm_work_columns WHERE board_id=$1 AND id=$2 AND version=$3 AND archived_at IS NOT NULL RETURNING id',[board,column,v]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,'column_permanently_deleted',JSON.stringify({column_id:column})]);return {ok:true}});
}
export async function permanentlyDeleteBoard(db,user,input){
 if(input?.confirmation!=='DELETE')throw Error('invalid_input');const board=id(input.id),v=version(input.version);
 return tx(db,user,null,async(c,a)=>{if(!a.admin)throw Error('forbidden');if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND version=$2 AND archived_at IS NOT NULL FOR UPDATE',[board,v])).rowCount)throw Error('version_conflict');if((await c.query('SELECT 1 FROM crm_work_cards WHERE board_id=$1 LIMIT 1',[board])).rowCount)throw Error('board_not_empty');await c.query('DELETE FROM crm_work_print_templates WHERE board_id=$1',[board]);await c.query('DELETE FROM crm_work_field_definitions WHERE board_id=$1',[board]);await c.query('DELETE FROM crm_work_columns WHERE board_id=$1',[board]);await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action) VALUES($1,$2,$3)',[board,user.id,'board_permanently_deleted']);await c.query('DELETE FROM crm_work_boards WHERE id=$1',[board]);return {ok:true}});
}
export async function deleteUnusedField(db,user,input){
 if(input?.confirmation!=='DELETE')throw Error('invalid_input');const board=id(input.boardId),field=id(input.id),v=version(input.version);
 return tx(db,user,null,async(c,a)=>{if(!a.admin)throw Error('forbidden');if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board])).rowCount)throw Error('not_found');const f=(await c.query('SELECT internal_name FROM crm_work_field_definitions WHERE board_id=$1 AND id=$2 AND version=$3 FOR UPDATE',[board,field,v])).rows[0];if(!f)throw Error('version_conflict');if((await c.query('SELECT 1 FROM crm_work_cards WHERE board_id=$1 AND custom_data ? $2 LIMIT 1',[board,f.internal_name])).rowCount||(await c.query('SELECT 1 FROM crm_work_print_templates WHERE board_id=$1 AND field_ids ? $2 LIMIT 1',[board,field])).rowCount)throw Error('field_in_use');await c.query('DELETE FROM crm_work_field_definitions WHERE id=$1 AND board_id=$2',[field,board]);await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,'field_deleted',JSON.stringify({field_id:field})]);return {ok:true}});
}
// A batch is all-or-nothing: every card must still be visible and at its expected version.
export async function bulkCards(db,user,input){
 const board=id(input?.boardId),action=input?.action;
 if(!['archive','restore','move','delete'].includes(action)||!Array.isArray(input.cards)||input.cards.length<1||input.cards.length>100||(action==='delete'&&input.confirmation!=='DELETE'))throw Error('invalid_input');
 const entries=input.cards.map(x=>({id:id(x?.id),version:version(x?.version)}));
 if(new Set(entries.map(x=>x.id)).size!==entries.length)throw Error('invalid_input');
 const destination=action==='move'?id(input.columnId):null;
 return tx(db,user,action==='move'?'edit':'archive',async(c,a)=>{
  if(action==='delete'&&!a.admin)throw Error('forbidden');
  if(!(await c.query('SELECT 1 FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board])).rowCount)throw Error('not_found');
  if(destination&&!(await c.query('SELECT 1 FROM crm_work_columns WHERE id=$1 AND board_id=$2 AND archived_at IS NULL',[destination,board])).rowCount)throw Error('not_found');
  const rows=(await c.query('SELECT id,version,archived_at,column_id FROM crm_work_cards WHERE board_id=$1 AND id=ANY($2::text[]) AND ($3::boolean OR assigned_user_id=$4) ORDER BY id FOR UPDATE',[board,entries.map(x=>x.id),a.all,user.id])).rows;
  if(rows.length!==entries.length||rows.some(row=>row.version!==entries.find(x=>x.id===row.id).version||Boolean(row.archived_at)!==(['restore','delete'].includes(action))))throw Error('version_conflict');
  let next=destination?(await c.query('SELECT coalesce(max(position)+1,0)::integer AS next FROM crm_work_cards WHERE board_id=$1 AND column_id=$2',[board,destination])).rows[0].next:0;
  for(const row of rows){
   if(action==='delete'){
    await c.query('DELETE FROM crm_work_cards WHERE board_id=$1 AND id=$2',[board,row.id]);
    await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action,details) VALUES($1,$2,$3,$4)',[board,user.id,'card_permanently_deleted',JSON.stringify({card_id:row.id,batch:true})]);
    continue;
   }
   if(action==='move')await c.query('UPDATE crm_work_cards SET column_id=$1,position=$2,version=version+1,updated_at=now() WHERE id=$3',[destination,next++,row.id]);
   else await c.query('UPDATE crm_work_cards SET archived_at=CASE WHEN $1 THEN now() ELSE NULL END,archived_by=CASE WHEN $1 THEN $2 ELSE NULL END,version=version+1,updated_at=now() WHERE id=$3',[action==='archive',user.id,row.id]);
   await c.query('INSERT INTO crm_work_card_events(board_id,card_id,actor_id,action,details) VALUES($1,$2,$3,$4,$5)',[board,row.id,user.id,action==='move'?'moved':action==='archive'?'archived':'restored',JSON.stringify(action==='move'?{from_column:row.column_id,to_column:destination,batch:true}:{batch:true})]);
  }
  return {updated:rows.length};
 });
}
export async function cardHistory(db,user,board,card){return tx(db,user,'history',async(c,a)=>{const r=await c.query(`SELECT e.id,e.action,e.actor_id,COALESCE(NULLIF(trim(concat_ws(' ',u.first_name,u.last_name)),''),e.actor_id) AS actor_name,CASE WHEN $5::boolean THEN e.details ELSE '{}'::jsonb END AS details,e.created_at FROM crm_work_card_events e JOIN users u ON u.id=e.actor_id JOIN crm_work_cards c ON c.id=e.card_id AND c.board_id=e.board_id WHERE e.board_id=$1 AND e.card_id=$2 AND ($3::boolean OR c.assigned_user_id=$4) AND EXISTS(SELECT 1 FROM crm_work_boards b WHERE b.id=e.board_id AND (b.archived_at IS NULL OR $5::boolean)) ORDER BY e.id DESC LIMIT 100`,[id(board),id(card),a.all,user.id,a.manage]);return r.rows})}
export async function moveCard(db,user,input){
 const a=await permission(db,user,'edit');const board=id(input.boardId),cardId=id(input.id),column=id(input.columnId),v=version(input.version);
 if(!Number.isSafeInteger(input.position)||input.position<0||input.position>10000)throw Error('invalid_input');
 return tx(db,user,'edit',async(c,a)=>{
  const locked=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(!locked.rowCount)throw Error('not_found');
  const target=await c.query('SELECT id FROM crm_work_columns WHERE id=$1 AND board_id=$2 AND archived_at IS NULL',[column,board]);if(!target.rowCount)throw Error('not_found');
  const current=await c.query('SELECT id,column_id,version FROM crm_work_cards WHERE id=$1 AND board_id=$2 AND archived_at IS NULL AND ($3::boolean OR assigned_user_id=$4) FOR UPDATE',[cardId,board,a.all,user.id]);if(!current.rowCount||current.rows[0].version!==v)throw Error('version_conflict');
  const old=current.rows[0].column_id;
  const items=await c.query('SELECT id FROM crm_work_cards WHERE board_id=$1 AND column_id=$2 AND archived_at IS NULL AND id<>$3 ORDER BY position,id FOR UPDATE',[board,column,cardId]);
  if(items.rows.length>10000)throw Error('limit_exceeded');
  const ordered=items.rows.map(x=>x.id);ordered.splice(Math.min(input.position,ordered.length),0,cardId);
  for(let i=0;i<ordered.length;i++)await c.query('UPDATE crm_work_cards SET column_id=$1,position=$2,version=version+1,updated_at=now() WHERE board_id=$3 AND id=$4',[column,i,board,ordered[i]]);
  if(old!==column){const previous=await c.query('SELECT id FROM crm_work_cards WHERE board_id=$1 AND column_id=$2 AND archived_at IS NULL ORDER BY position,id FOR UPDATE',[board,old]);for(let i=0;i<previous.rows.length;i++)await c.query('UPDATE crm_work_cards SET position=$1,version=version+1,updated_at=now() WHERE board_id=$2 AND id=$3 AND position<>$1',[i,board,previous.rows[i].id])}
  await c.query('INSERT INTO crm_work_card_events(board_id,card_id,actor_id,action,details) VALUES($1,$2,$3,$4,$5)',[board,cardId,user.id,'moved',JSON.stringify({from_column:old,to_column:column,position:input.position})]);return safeCard((await c.query('SELECT * FROM crm_work_cards WHERE id=$1',[cardId])).rows[0]);
 });
}
export async function getVisibility(db,user,subjectId){return tx(db,user,null,async(c,a)=>{if(!a.admin)throw Error('forbidden');const subject=id(subjectId);const r=await c.query("SELECT coalesce((SELECT scope FROM crm_work_user_visibility WHERE user_id=$1),'inherit') AS scope,coalesce((SELECT max(id) FROM crm_work_visibility_history WHERE user_id=$1),0)::text AS revision",[subject]);return r.rows[0]})}
export async function setVisibility(db,user,input){
 if(!user||user.role!=='admin')throw Error('forbidden');if(!['inherit','all','own'].includes(input?.scope)||typeof input.expectedRevision!=='string'||!/^\d{1,18}$/.test(input.expectedRevision))throw Error('invalid_input');
 const subject=id(input.userId),c=await db.connect();
 try{await c.query('BEGIN');await c.query('SELECT pg_advisory_xact_lock($1)',[68499002]);const users=await c.query('SELECT id,role,active FROM users WHERE id=ANY($1::text[]) ORDER BY id FOR UPDATE',[[user.id,subject]]);const actor=users.rows.find(x=>x.id===user.id),target=users.rows.find(x=>x.id===subject);if(!actor?.active||actor.role!=='admin'||!target)throw Error('forbidden');await requireLiveSession(c,user.id);const old=(await c.query('SELECT scope FROM crm_work_user_visibility WHERE user_id=$1',[subject])).rows[0]?.scope||'inherit';const revision=(await c.query('SELECT coalesce(max(id),0)::text AS revision FROM crm_work_visibility_history WHERE user_id=$1',[subject])).rows[0].revision;if(revision!==input.expectedRevision)throw Error('version_conflict');const r=await c.query(`INSERT INTO crm_work_user_visibility(user_id,scope,updated_by) VALUES($1,$2,$3) ON CONFLICT(user_id) DO UPDATE SET scope=EXCLUDED.scope,updated_by=EXCLUDED.updated_by,updated_at=now() RETURNING user_id,scope`,[subject,input.scope,user.id]);if(old!==input.scope)await c.query('INSERT INTO crm_work_visibility_history(user_id,actor_id,old_scope,new_scope) VALUES($1,$2,$3,$4)',[subject,user.id,old,input.scope]);await c.query('COMMIT');return r.rows[0]}catch(e){await c.query('ROLLBACK').catch(()=>{});throw e}finally{c.release()}
}
export async function reorderColumns(db,user,input){await permission(db,user,'manage');const board=id(input.boardId);if(!Array.isArray(input.columns)||input.columns.length>200||new Set(input.columns).size!==input.columns.length)throw Error('invalid_input');const ordered=input.columns.map(id);return tx(db,user,'manage',async c=>{const b=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(!b.rowCount)throw Error('not_found');const current=await c.query('SELECT id FROM crm_work_columns WHERE board_id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(current.rowCount!==ordered.length||current.rows.some(x=>!ordered.includes(x.id)))throw Error('version_conflict');for(let i=0;i<ordered.length;i++)await c.query('UPDATE crm_work_columns SET position=$1,version=version+1 WHERE id=$2 AND board_id=$3',[i,ordered[i],board]);return {ok:true}})}

export async function listAssignees(db,user){return tx(db,user,'edit',async(c,a)=>{if(!a.all)return {users:[],canAssign:false};const r=await c.query("SELECT u.id,COALESCE(NULLIF(trim(concat_ws(' ',u.first_name,u.last_name)),''),u.email) AS name FROM users u WHERE u.active=true AND (u.role='admin' OR EXISTS(SELECT 1 FROM staff_permissions p WHERE p.user_id=u.id AND p.permission='crm_boards_view') OR EXISTS(SELECT 1 FROM access_role_assignments a JOIN access_roles r ON r.id=a.role_id WHERE a.user_id=u.id AND 'crm_boards_view'=ANY(r.permissions))) ORDER BY name,u.id LIMIT 200");return {users:r.rows,canAssign:true}})}
export async function reorderFields(db,user,input){const board=id(input.boardId);if(!Array.isArray(input.fields)||input.fields.length>200||new Set(input.fields).size!==input.fields.length)throw Error('invalid_input');const ordered=input.fields.map(id);return tx(db,user,'manage',async c=>{const b=await c.query('SELECT id FROM crm_work_boards WHERE id=$1 AND archived_at IS NULL FOR UPDATE',[board]);if(!b.rowCount)throw Error('not_found');const current=await c.query('SELECT id FROM crm_work_field_definitions WHERE board_id=$1 FOR UPDATE',[board]);if(current.rowCount!==ordered.length||current.rows.some(x=>!ordered.includes(x.id)))throw Error('version_conflict');for(let i=0;i<ordered.length;i++)await c.query('UPDATE crm_work_field_definitions SET position=$1,version=version+1 WHERE id=$2 AND board_id=$3',[i,ordered[i],board]);await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action) VALUES($1,$2,$3)',[board,user.id,'fields_reordered']);return {ok:true}})}
export async function reorderBoards(db,user,input){if(!Array.isArray(input?.boards)||input.boards.length>200||new Set(input.boards).size!==input.boards.length)throw Error('invalid_input');const ordered=input.boards.map(id);return tx(db,user,'manage',async c=>{const current=await c.query('SELECT id FROM crm_work_boards WHERE archived_at IS NULL FOR UPDATE');if(current.rowCount!==ordered.length||current.rows.some(x=>!ordered.includes(x.id)))throw Error('version_conflict');for(let i=0;i<ordered.length;i++)await c.query('UPDATE crm_work_boards SET position=$1,version=version+1,updated_at=now() WHERE id=$2',[i,ordered[i]]);if(ordered.length)await c.query('INSERT INTO crm_work_board_events(board_id,actor_id,action) VALUES($1,$2,$3)',[ordered[0],user.id,'boards_reordered']);return {ok:true}})}
export async function boardHistory(db,user,board){return tx(db,user,'history',async(c,a)=>{const r=await c.query(`SELECT e.id,e.action,e.actor_id,COALESCE(NULLIF(trim(concat_ws(' ',u.first_name,u.last_name)),''),e.actor_id) AS actor_name,CASE WHEN $2::boolean THEN e.details ELSE '{}'::jsonb END AS details,e.created_at FROM crm_work_board_events e JOIN users u ON u.id=e.actor_id JOIN crm_work_boards b ON b.id=e.board_id WHERE e.board_id=$1 AND (b.archived_at IS NULL OR $2::boolean) ORDER BY e.id DESC LIMIT 100`,[id(board),a.manage]);return r.rows})}
export async function checkCardAccess(db,user,board,card){return tx(db,user,null,async(c,a)=>{const r=await c.query(`SELECT 1 FROM crm_work_cards c JOIN crm_work_boards b ON b.id=c.board_id WHERE c.board_id=$1 AND c.id=$2 AND b.archived_at IS NULL AND ($3::boolean OR c.assigned_user_id=$4)`,[id(board),id(card),a.all,user.id]);if(!r.rowCount)throw Error('not_found');return {visible:true}})}
function shiftDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('invalid_input');const d=new Date(v+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('invalid_input');return v}
function shiftTime(v){if(typeof v!=='string'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))throw Error('invalid_input');return v}
export async function listStaffShifts(db,user,input){
 const from=shiftDate(input?.from),to=shiftDate(input?.to),days=(Date.parse(to)-Date.parse(from))/86400000;
 if(days<0||days>90)throw Error('invalid_input');
 return tx(db,user,null,async(c,a)=>(await c.query(`SELECT s.id,s.user_id,s.shift_date::text,s.start_time::text,s.end_time::text,s.role_label,s.location,s.notes,s.version,COALESCE(NULLIF(trim(concat_ws(' ',u.first_name,u.last_name)),''),u.email) AS user_name FROM crm_staff_shifts s JOIN users u ON u.id=s.user_id WHERE s.shift_date BETWEEN $1 AND $2 AND s.canceled_at IS NULL AND ($3::boolean OR s.user_id=$4) ORDER BY s.shift_date,s.start_time,s.id LIMIT 500`,[from,to,a.admin,user.id])).rows);
}
export async function saveStaffShift(db,user,input){
 const target=id(input?.userId),date=shiftDate(input?.date),start=shiftTime(input?.start),end=shiftTime(input?.end);
 if(end<=start)throw Error('invalid_input');
 const optional=(x,max)=>{if(typeof x!=='string'||x.length>max||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(x))throw Error('invalid_input');return x.trim()};
 const role=optional(input.role??'',120),location=optional(input.location??'',200),notes=optional(input.notes??'',2000);
 return tx(db,user,null,async(c,a)=>{
  if(!a.admin)throw Error('forbidden');
  if(!(await c.query('SELECT 1 FROM users WHERE id=$1 AND active=true',[target])).rowCount)throw Error('invalid_input');
  let r;if(input.id)r=await c.query('UPDATE crm_staff_shifts SET user_id=$1,shift_date=$2,start_time=$3,end_time=$4,role_label=$5,location=$6,notes=$7,version=version+1,updated_at=now() WHERE id=$8 AND version=$9 AND canceled_at IS NULL RETURNING id,version',[target,date,start,end,role,location,notes,id(input.id),version(input.version)]);
  else r=await c.query('INSERT INTO crm_staff_shifts(id,user_id,shift_date,start_time,end_time,role_label,location,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id,version',[randomUUID(),target,date,start,end,role,location,notes,user.id]);
  if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_staff_shift_events(actor_id,shift_id,action) VALUES($1,$2,$3)',[user.id,r.rows[0].id,input.id?'updated':'created']);return r.rows[0];
 });
}
export async function cancelStaffShift(db,user,input){return tx(db,user,null,async(c,a)=>{if(!a.admin)throw Error('forbidden');const r=await c.query('UPDATE crm_staff_shifts SET canceled_at=now(),version=version+1,updated_at=now() WHERE id=$1 AND version=$2 AND canceled_at IS NULL RETURNING id',[id(input?.id),version(input?.version)]);if(!r.rowCount)throw Error('version_conflict');await c.query('INSERT INTO crm_staff_shift_events(actor_id,shift_id,action) VALUES($1,$2,$3)',[user.id,r.rows[0].id,'canceled']);return {ok:true}})}
